tape( 'the function throws an error if provided a fourth argument which is not a valid `LDA` value (row-major)', function test( t ) {
	var values;
	var data;
	var work;
	var A;
	var i;

	data = FROBENIUS_NORM_ROW_MAJOR;

	values = [
		0,
		1,
		2,
		3
	];

	A = new Float64Array( data.A );
	work = new Float64Array( data.work );

	for ( i = 0; i < values.length; i++ ) {
		t.throws( badValue( values[ i ] ), RangeError, 'throws an error when provided ' + values[ i ] );
	}
	t.end();

	function badValue( value ) {
		return function badValue() {
			dlange( data.order, data.norm, data.M, data.N, A, value, work );
		};
	}
});

tape( 'the function calculates the one norm for a given matrix A (row-major)', function test( t ) {
	var data;
	var work;
	var out;
	var A;

	data = ONE_NORM_ROW_MAJOR;

	A = new Float64Array( data.A );
	work = new Float64Array( data.work );

	out = dlange( data.order, data.norm, data.M, data.N, A, data.LDA, work );
	t.strictEqual( out, data.expected, 'returns expected value' );
	t.end();
});

